(7081088, 1077414, 161157, '<td valign="top">That is an awesome picture. I love it. Congratulations.</td>', 'That is an awesome picture. I love it. Congratulations.', '2013-08-03 04:16:27.000000', NULL, 1),
(7081507, 1077544, 87808, '<td valign="top">I really like this entry.  The unexpected touch of the name of the book , shows that you went out of your way to put some soul into this challenge.  Black is a really hard colour to shoot with and edit, as you can see with your tinge of purple.  But you have a fabulous colour in that purple, it is a deep rich vibrant black/purple, very much and similar to a Walker ink pot ink.  The only real thing I will nit pick on is the red lines on the desk on the left hand side, it works on the right as it shows the ridge detail of the desk, but as it has totally faded back into black on the left hand side, it is just coming up as red lines.  Fantastic job, you should be proud.</td>', 'I really like this entry.  The unexpected touch of the name of the book , shows that you went out of your way to put some soul into this challenge.  Black is a really hard colour to shoot with and edit, as you can see with your tinge of purple.  But you have a fabulous colour in that purple, it is a deep rich vibrant black/purple, very much and similar to a Walker ink pot ink.  The only real thing I will nit pick on is the red lines on the desk on the left hand side, it works on the right as it shows the ridge detail of the desk, but as it has totally faded back into black on the left hand side, it is just coming up as red lines.  Fantastic job, you should be proud.', '2013-08-04 15:31:06.000000', NULL, 1),
(7081508, 1077537, 87808, '<td valign="top">I would really have liked to seen one spot in this shot that was in focus, the lower left hand corner is the sharpest. I do like the neon green hints though, it does make it stand out</td>', 'I would really have liked to seen one spot in this shot that was in focus, the lower left hand corner is the sharpest. I do like the neon green hints though, it does make it stand out', '2013-08-04 15:33:02.000000', NULL, 1),
(7081510, 1077512, 87808, '<td valign="top">Fabulous , and interesting capture, not a lot of these shot on DPC, so kudo''s on this, love the tack sharp whiskers, well done!</td>', 'Fabulous , and interesting capture, not a lot of these shot on DPC, so kudo''s on this, love the tack sharp whiskers, well done!', '2013-08-04 15:34:30.000000', NULL, 1),
(7081511, 1077002, 87808, '<td valign="top">Great use of your lighting here, maybe just a tiny dodge on the right hand chin, so it ties with the lighting on the skull''s skull and cheekbone.  7</td>', 'Great use of your lighting here, maybe just a tiny dodge on the right hand chin, so it ties with the lighting on the skull''s skull and cheekbone.  7', '2013-08-04 15:35:46.000000', NULL, 1),
(7081512, 1077409, 87808, '<td valign="top">How can this not be a 9/  Tack sharp nose, and eyes, an angle that you would normally not see so much detail in the eyes .  Really fabulous and the lighting is outstanding</td>', 'How can this not be a 9/  Tack sharp nose, and eyes, an angle that you would normally not see so much detail in the eyes .  Really fabulous and the lighting is outstanding', '2013-08-04 15:36:41.000000', NULL, 1),
(7081515, 1077445, 87808, '<td valign="top">I can see this one being a Sieg, if not then you have been complimented, I do find the light on the fingers a little harsh though, but bar that, fab shot!</td>', 'I can see this one being a Sieg, if not then you have been complimented, I do find the light on the fingers a little harsh though, but bar that, fab shot!', '2013-08-04 15:53:00.000000', NULL, 1),
(7081517, 1077545, 87808, '<td valign="top">OHHHH I like it, you really have got it quite well.  The only thing I am going to say is the toes of this statue are showing too much, but tilt the screen upwards and they disappear and you have a stunning black on black subject</td>', 'OHHHH I like it, you really have got it quite well.  The only thing I am going to say is the toes of this statue are showing too much, but tilt the screen upwards and they disappear and you have a stunning black on black subject', '2013-08-04 15:54:43.000000', NULL, 1),
(7081519, 1077138, 87808, '<td valign="top">Nicely done, tack sharp, good rules, interesting comp with the needle, that just makes the picture, some real thought went into this very simple subject to make it stand out. 8</td>', 'Nicely done, tack sharp, good rules, interesting comp with the needle, that just makes the picture, some real thought went into this very simple subject to make it stand out. 8', '2013-08-04 15:56:37.000000', NULL, 1),
(7081521, 1077431, 87808, '<td valign="top">How can this not be a top score.  tack sharp detail, interesting details, fabulous portrait without eye contact. Only nit picking I am going to do is the stall bars in the background.  I have found that tilting the screen of your comp when finished with a black and black subject, it will show you any light area''s.  9</td>', 'How can this not be a top score.  tack sharp detail, interesting details, fabulous portrait without eye contact. Only nit picking I am going to do is the stall bars in the background.  I have found that tilting the screen of your comp when finished with a black and black subject, it will show you any light area''s.  9', '2013-08-04 15:58:42.000000', NULL, 1),
(7081523, 1077543, 87808, '<td valign="top">I like this one, the eyes are getting lost though, just a tiny tiny bit of brightness on the whites in the eyes would have tied it up with the mouth and the hair light. 7</td>', 'I like this one, the eyes are getting lost though, just a tiny tiny bit of brightness on the whites in the eyes would have tied it up with the mouth and the hair light. 7', '2013-08-04 15:59:35.000000', NULL, 1),
(7081524, 1077354, 87808, '<td valign="top">Veggies/fruit can be so boring sometimes, but this is really well done, your two sharp stems really set this off 7</td>', 'Veggies/fruit can be so boring sometimes, but this is really well done, your two sharp stems really set this off 7', '2013-08-04 16:00:26.000000', NULL, 1),
(7081539, 1077046, 87808, '<td valign="top">Thta is some seriously straight rain!!!  nice capture</td>', 'Thta is some seriously straight rain!!!  nice capture', '2013-08-04 17:10:11.000000', NULL, 1),
(7081544, 1077112, 87808, '<td valign="top">Nice sharpness and great emotive shot, well done 8</td>', 'Nice sharpness and great emotive shot, well done 8', '2013-08-04 17:13:51.000000', NULL, 1),
(7081545, 1077107, 87808, '<td valign="top">LOLOL brilliant 7</td>', 'LOLOL brilliant 7', '2013-08-04 17:15:29.000000', NULL, 1),
(7081546, 1077105, 87808, '<td valign="top">Tack sharp, clean and clear, excellent portrait, very well done 9</td>', 'Tack sharp, clean and clear, excellent portrait, very well done 9', '2013-08-04 17:16:26.000000', NULL, 1),
(7081547, 1077374, 87808, '<td valign="top">I like it, love the pop of colour as well, nicely done</td>', 'I like it, love the pop of colour as well, nicely done', '2013-08-04 17:17:04.000000', NULL, 1),
(7081548, 1077376, 87808, '<td valign="top">Very nice as it does tell a story instead of being just plopped there, lovely lighting, tack sharp, clean lines, good rules usage. 9</td>', 'Very nice as it does tell a story instead of being just plopped there, lovely lighting, tack sharp, clean lines, good rules usage. 9', '2013-08-04 17:19:51.000000', NULL, 1),
(7081549, 1077388, 87808, '<td valign="top">Very regal, I do like this very much, especially the whites in it, it gives it a good dimension, usually I do not like any shots that do not have one point of sharpness, but this is soft in the correct way nad it really really works. 9</td>', 'Very regal, I do like this very much, especially the whites in it, it gives it a good dimension, usually I do not like any shots that do not have one point of sharpness, but this is soft in the correct way nad it really really works. 9', '2013-08-04 17:21:32.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7081550, 1077406, 87808, '<td valign="top">Nice rim lighting on this, I am sure people have said something about the colour though, maybe doing a layer in black and white and just reducing op, to take a slight hint of the colour out, not much just a little.  But the biggest problem you have is that thick solid black line running through it, a shame 5</td>', 'Nice rim lighting on this, I am sure people have said something about the colour though, maybe doing a layer in black and white and just reducing op, to take a slight hint of the colour out, not much just a little.  But the biggest problem you have is that thick solid black line running through it, a shame 5', '2013-08-04 17:23:35.000000', NULL, 1),
