(7082043, 1077112, 144271, '<td valign="top">This makes me happy to look at.</td>', 'This makes me happy to look at.', '2013-08-05 19:53:04.000000', NULL, 1),
(7082111, 1077208, 115814, '<td valign="top">Allusions of spinning and ultrasounds and Zappa ("let''s make the water turn black"). Love it!</td>', 'Allusions of spinning and ultrasounds and Zappa ("let''s make the water turn black"). Love it!', '2013-08-05 23:22:28.000000', NULL, 1),
(7082112, 1077536, 115814, '<td valign="top">Lovely. Singular subject and frame filling wonderfulness. Hints of pearls on paper bark. Nice!</td>', 'Lovely. Singular subject and frame filling wonderfulness. Hints of pearls on paper bark. Nice!', '2013-08-05 23:24:00.000000', NULL, 1),
(7082116, 1077409, 115814, '<td valign="top">(S)he''s so intent! I can imagine the intensity of attention on something out of the frame. Top-notch tonal management, too. Bravo!</td>', '(S)he''s so intent! I can imagine the intensity of attention on something out of the frame. Top-notch tonal management, too. Bravo!', '2013-08-05 23:25:43.000000', NULL, 1),
(7082118, 1077425, 115814, '<td valign="top">Love the lines and shapes and understated tones. Well done!</td>', 'Love the lines and shapes and understated tones. Well done!', '2013-08-05 23:27:15.000000', NULL, 1),
(7082125, 1077374, 115814, '<td valign="top">The astroid, "City Water Meter" enters the atmosphere. What might have been interesting becomes fascinating with the emphasis on the blues and bronze of the upper right. Nicely seen and processed.</td>', 'The astroid, "City Water Meter" enters the atmosphere. What might have been interesting becomes fascinating with the emphasis on the blues and bronze of the upper right. Nicely seen and processed.', '2013-08-05 23:30:23.000000', NULL, 1),
(7082136, 1077305, 115814, '<td valign="top">Definitely a top pick. The exceptional  tone management, composition and framing come together to create what may be the best response to the challenge of the bunch!</td>', 'Definitely a top pick. The exceptional  tone management, composition and framing come together to create what may be the best response to the challenge of the bunch!', '2013-08-05 23:39:33.000000', NULL, 1),
(7082138, 1077511, 115814, '<td valign="top">A beautiful take on this challenge. I wish you had a little more room at the bottom. Otherwise, one of my favorites of the challenge. Nice work.</td>', 'A beautiful take on this challenge. I wish you had a little more room at the bottom. Otherwise, one of my favorites of the challenge. Nice work.', '2013-08-05 23:40:51.000000', NULL, 1),
(7082140, 1077445, 115814, '<td valign="top">Very nice exposure control. Love the touch of red, too. I do find my attention torn between the fingers and the bow/hat, though.</td>', 'Very nice exposure control. Love the touch of red, too. I do find my attention torn between the fingers and the bow/hat, though.', '2013-08-05 23:42:28.000000', NULL, 1),
(7082145, 1077339, 115814, '<td valign="top">Back to bump the score. This one gets better the more I look. It implies magic to me and the fact that all the highlights are floating inside a black cushion on the edges amplifies the mystery. Nice!</td>', 'Back to bump the score. This one gets better the more I look. It implies magic to me and the fact that all the highlights are floating inside a black cushion on the edges amplifies the mystery. Nice!', '2013-08-05 23:44:22.000000', NULL, 1),
(7082147, 1077544, 115814, '<td valign="top">Excellent composition, lines, details.</td>', 'Excellent composition, lines, details.', '2013-08-05 23:45:19.000000', NULL, 1),
(7082169, 1077409, 136989, '<td valign="top">Gorgeous puppy and wonderful black on black.  So silky.</td>', 'Gorgeous puppy and wonderful black on black.  So silky.', '2013-08-05 23:55:18.000000', NULL, 1),
(7082171, 1077217, 136989, '<td valign="top">Nice lighting and details.</td>', 'Nice lighting and details.', '2013-08-05 23:55:41.000000', NULL, 1),
